<?php require __DIR__.'/../../app/core/bootstrap.php'; header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'POST required']);exit;}$d=json_decode(file_get_contents('php://input'),true) ?: $_POST;foreach(['nim','name','email','class_name','study_program','faculty','semester','password'] as $f)if(empty($d[$f])){http_response_code(422);echo json_encode(['error'=>"Field $f wajib"]) ;exit;}if(strlen($d['password'])<8){http_response_code(422);echo json_encode(['error'=>'Password minimal 8 karakter']);exit;}$rid=$pdo->query("SELECT id FROM roles WHERE name='pengguna'")->fetchColumn();try{$st=$pdo->prepare('INSERT INTO users(role_id,nim,name,email,class_name,study_program,faculty,semester,password_hash) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$rid,trim($d['nim']),trim($d['name']),trim($d['email']),trim($d['class_name']),trim($d['study_program']),trim($d['faculty']),(int)$d['semester'],password_hash($d['password'],PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();log_activity($pdo,$id,'pengguna','Pendaftaran API','Akun dibuat via API');echo json_encode(['success'=>true,'id'=>$id]);}catch(Throwable $e){http_response_code(409);echo json_encode(['error'=>'NIM/email sudah digunakan']);}
